#include <iostream>
#include <vector>
#include <algorithm>
#include <cstring>
#include <cstdint>
using namespace std;

using i64 = int64_t;
constexpr i64 MOD = 1000000007LL;

i64 mod_pow(i64 b, i64 e) {
    i64 r = 1;
    while (e) {
        if (e & 1) r = r * b % MOD;
        b = b * b % MOD;
        e >>= 1;
    }
    return r;
}

int N, M;
i64 dp1[(1<<20)], dp2[(1<<20)];
i64 P[10][10];
int idx1[(1<<20)], idx2[(1<<20)];
int corr[25];

void enumerate1(int cur, vector<int>& cur_vec, i64 prob_val) {
    if (cur == M) {
        int mask = 0, cnt = 0;
        for (int s = 0; s < (1<<N); ++s) {
            if (__builtin_popcount(s) != M) continue;
            vector<int> v;
            for (int i = 0; i < N; ++i)
                if (s >> i & 1) v.push_back(i);
            sort(v.begin(), v.end());
            bool found = false;
            do {
                bool ok = true;
                for (int j = 0; j < M; ++j)
                    if (!(cur_vec[j] >> v[j] & 1)) { ok = false; break; }
                if (ok) { found = true; break; }
            } while (next_permutation(v.begin(), v.end()));
            if (found) mask |= 1 << cnt;
            ++cnt;
        }
        dp1[mask] = (dp1[mask] + prob_val) % MOD;
        return;
    }

    for (int s = 0; s < (1<<N); ++s) {
        cur_vec.push_back(s);
        i64 new_prob = prob_val;
        for (int j = 0; j < N; ++j) {
            if (s >> j & 1)
                new_prob = new_prob * P[cur][j] % MOD;
            else
                new_prob = new_prob * (MOD + 1 - P[cur][j]) % MOD;
        }
        enumerate1(cur + 1, cur_vec, new_prob);
        cur_vec.pop_back();
    }
}

void enumerate2(int cur, vector<int>& cur_vec, i64 prob_val) {
    if (cur == N) {
        int mask = 0, cnt = 0;
        for (int s = 0; s < (1<<N); ++s) {
            if (__builtin_popcount(s) != N - M) continue;
            vector<int> v;
            for (int i = 0; i < N; ++i)
                if (s >> i & 1) v.push_back(i);
            sort(v.begin(), v.end());
            bool found = false;
            do {
                bool ok = true;
                for (int j = 0; j < N - M; ++j)
                    if (!(cur_vec[j] >> v[j] & 1)) { ok = false; break; }
                if (ok) { found = true; break; }
            } while (next_permutation(v.begin(), v.end()));
            if (found) mask |= 1 << cnt;
            ++cnt;
        }
        dp2[mask] = (dp2[mask] + prob_val) % MOD;
        return;
    }

    for (int s = 0; s < (1<<N); ++s) {
        cur_vec.push_back(s);
        i64 new_prob = prob_val;
        for (int j = 0; j < N; ++j) {
            if (s >> j & 1)
                new_prob = new_prob * P[cur][j] % MOD;
            else
                new_prob = new_prob * (MOD + 1 - P[cur][j]) % MOD;
        }
        enumerate2(cur + 1, cur_vec, new_prob);
        cur_vec.pop_back();
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            int x; cin >> x;
            P[i][j] = 1LL * x * mod_pow(100, MOD-2) % MOD;
            if (P[i][j] < 0) P[i][j] += MOD;
        }

    if (N == 1) {
        cout << P[0][0] << '\n';
        return 0;
    }

    M = N / 2;
    vector<int> cur;
    enumerate1(0, cur, 1);

    for (int i = 0; i < (1<<20); ++i) dp1[i] %= MOD;

    for (int b = 0; b < 20; ++b)
        for (int s = 0; s < (1<<20); ++s)
            if (s >> b & 1)
                dp1[s] = (dp1[s] + dp1[s ^ (1<<b)]) % MOD;

    i64 total = dp1[(1<<20)-1];

    cur.clear();
    enumerate2(M, cur, 1);

    for (int i = 0; i < (1<<20); ++i) dp2[i] %= MOD;

    fill(idx1, idx1 + (1<<20), -1);
    int cnt = 0;
    for (int s = 0; s < (1<<N); ++s) {
        if (__builtin_popcount(s) != M) continue;
        idx1[s] = cnt++;
    }

    fill(idx2, idx2 + (1<<20), -1);
    cnt = 0;
    for (int s = 0; s < (1<<N); ++s) {
        if (__builtin_popcount(s) != N - M) continue;
        corr[cnt] = idx1[(1<<N) - 1 - s];
        idx2[s] = cnt++;
    }

    i64 ans = 0;
    for (int s = 0; s < (1<<cnt); ++s) {
        i64 val = dp2[s];
        int mask = 0;
        for (int b = 0; b < cnt; ++b) {
            if (s >> b & 1) continue;
            mask |= 1 << corr[b];
        }
        ans = (ans + val * ((total - dp1[mask] + MOD) % MOD)) % MOD;
    }

    cout << ans % MOD << '\n';
    return 0;
}
